import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  formatPostalCode,
  groupCard,
  groupSheba,
  isValidNationalId,
  luhnCheck,
  mobileOperator,
  normalizeDigits,
  normalizeMobile,
  validateBankCard,
  validateMobile,
  validateNationalId,
  validatePlate,
  validatePostalCode,
  validateSheba,
  validateUsername,
} from "./iran-ids";

/**
 * The valid samples below were generated by running the checksum *forwards*
 * (compute the check digit for a 9-digit body) rather than copied from a
 * random website, so each one is provably correct by construction.
 */

describe("normalizeDigits", () => {
  it("folds Persian and Arabic-Indic digits to ASCII", () => {
    assert.equal(normalizeDigits("۱۲۳۴۵۶۷۸۹۰"), "1234567890");
    assert.equal(normalizeDigits("١٢٣٤٥٦٧٨٩٠"), "1234567890");
  });

  it("removes separators people paste in", () => {
    assert.equal(normalizeDigits("6037 9912-3456_7890"), "6037991234567890");
  });
});

describe("validateNationalId", () => {
  it("accepts valid IDs (check digit computed forward)", () => {
    for (const id of ["0012345679", "0079836356", "1234567891", "0499370899"]) {
      const result = validateNationalId(id);
      assert.equal(result.ok, true, `${id} → ${result.error}`);
    }
  });

  it("accepts a valid ID written with Persian digits", () => {
    assert.equal(isValidNationalId("۰۰۱۲۳۴۵۶۷۹"), true);
  });

  it("rejects a wrong check digit", () => {
    const result = validateNationalId("0012345678");
    assert.equal(result.ok, false);
    assert.match(result.error ?? "", /رقم کنترل/);
  });

  it("rejects wrong lengths and the all-same-digit shortcut", () => {
    assert.equal(validateNationalId("123456789").ok, false);
    assert.equal(validateNationalId("12345678901").ok, false);
    // passes the mod-11 sum but is explicitly invalid per the civil registry
    assert.equal(validateNationalId("1111111111").ok, false);
  });

  it("requires a value", () => {
    assert.equal(validateNationalId("").ok, false);
  });
});

describe("mobile numbers", () => {
  it("canonicalises every common way of writing one number", () => {
    const expected = "09123456789";
    for (const raw of [
      "09123456789",
      "۰۹۱۲۳۴۵۶۷۸۹",
      "+989123456789",
      "00989123456789",
      "989123456789",
      "9123456789",
      "0912 345 6789",
    ]) {
      assert.equal(normalizeMobile(raw).value, expected, raw);
    }
  });

  it("rejects a landline and an unknown prefix", () => {
    assert.equal(validateMobile("02188776655").ok, false);
    assert.equal(validateMobile("04123456789").ok, false);
  });

  it("names the operator", () => {
    assert.equal(mobileOperator("09121234567"), "همراه اول");
    assert.equal(mobileOperator("09351234567"), "رایتل");
    assert.equal(mobileOperator("09011234567"), "ایرانسل");
  });
});

describe("bank cards (Luhn)", () => {
  it("accepts Luhn-valid cards built from real BINs", () => {
    const cases: Array<[string, string]> = [
      ["6037991234567893", "بانک ملی ایران"],
      ["6104331234567890", "بانک ملت"],
      ["5022291234567897", "بانک پاسارگاد"],
    ];
    for (const [card, bank] of cases) {
      const result = validateBankCard(card);
      assert.equal(result.ok, true, `${card} → ${result.error}`);
      assert.equal(result.meta?.bank, bank);
    }
  });

  it("rejects a single mistyped digit", () => {
    assert.equal(validateBankCard("6037991234567894").ok, false);
  });

  it("rejects wrong length", () => {
    assert.equal(validateBankCard("603799123456789").ok, false);
  });

  it("luhnCheck is the plain mod-10 rule", () => {
    assert.equal(luhnCheck("4111111111111111"), true);
    assert.equal(luhnCheck("4111111111111112"), false);
  });

  it("groups for display", () => {
    assert.equal(groupCard("6037991234567890"), "6037 9912 3456 7890");
  });
});

describe("sheba (IBAN)", () => {
  it("accepts mod-97 valid values", () => {
    for (const s of ["IR110620000000123456789012", "IR160120000000001234567890"]) {
      const result = validateSheba(s);
      assert.equal(result.ok, true, `${s} → ${result.error}`);
    }
  });

  it("accepts lowercase and spaced input", () => {
    assert.equal(validateSheba("ir11 0620 0000 0012 3456 7890 12").ok, true);
  });

  it("rejects a broken check part", () => {
    assert.equal(validateSheba("IR120620000000123456789012").ok, false);
  });

  it("rejects wrong length and missing IR", () => {
    assert.equal(validateSheba("620000000123456789012").ok, false);
    assert.equal(validateSheba("IR0620000000123456789").ok, false);
  });

  it("groups for display", () => {
    assert.equal(groupSheba("IR110620000000123456789012"), "IR1106 2000 0000 1234 5678 9012");
  });
});

describe("postal code", () => {
  it("accepts structural shapes that follow the rules", () => {
    assert.equal(validatePostalCode("1234567890").ok, true);
    assert.equal(validatePostalCode("۱۹۱۹۸۸۴۵۶۷").ok, true);
  });

  it("rejects runs of identical digits", () => {
    assert.equal(validatePostalCode("1111111111").ok, false);
    assert.equal(validatePostalCode("1233334567").ok, false);
  });

  it("rejects wrong length", () => {
    assert.equal(validatePostalCode("123456789").ok, false);
  });

  it("formats as 5-5", () => {
    assert.equal(formatPostalCode("1234567890"), "12345-67890");
  });
});

describe("licence plates", () => {
  it("parses a national plate", () => {
    const result = validatePlate("۱۲ب۳۴۵۶۷");
    assert.equal(result.ok, true);
    assert.deepEqual(result.meta, { letter: "ب", left: "12", right: "345", province: "67" });
  });

  it("parses a free-zone plate", () => {
    const result = validatePlate("345ب12");
    assert.equal(result.ok, true);
    assert.equal(result.meta?.province, "");
  });

  it("accepts a Latin letter keyed for a Persian one", () => {
    assert.equal(validatePlate("12B34567").ok, true);
  });

  it("rejects a letter that is not on plates", () => {
    assert.equal(validatePlate("12X34567").ok, false);
  });

  it("rejects an unrecognised shape", () => {
    assert.equal(validatePlate("1234567890").ok, false);
  });
});

describe("username", () => {
  it("accepts ordinary Persian and Latin usernames", () => {
    assert.equal(validateUsername("ali_1990").ok, true);
    assert.equal(validateUsername("مهدی.رضا").ok, true);
  });

  it("rejects too short, starting with a digit, and bad characters", () => {
    assert.equal(validateUsername("ali").ok, false);
    assert.equal(validateUsername("1ali1990").ok, false);
    assert.equal(validateUsername("ali reza!!").ok, false);
  });
});
